constexpr uint32_t SYNC_FUTURE_SKEW = 300;
constexpr uint32_t SYNC_MAX_LOOKAHEAD = 8U * SECONDS_PER_DAY;

struct SyncTimestamp {
  uint32_t seconds = 0;
  uint16_t milliseconds = 0;
  SyncTimestamp() = default;
  explicit SyncTimestamp(uint32_t sec, uint16_t fraction = 0) : seconds(sec), milliseconds(fraction) {}
  uint64_t value() const { return uint64_t(seconds) * 1000 + milliseconds; }
  bool operator==(const SyncTimestamp& other) const { return value() == other.value(); }
};

enum class SyncPhase : uint8_t { Empty, Scheduled, Consumed, Started, Completed, Skipped, Stopped, Cancelled, Interrupted };

struct PhoneSyncRecord {
  uint32_t revision = 0, profileRevision = 0, consumedThrough = 0;
  SyncTimestamp capturedAt, wakeAt;
  SyncPhase phase = SyncPhase::Empty;
  bool enabled = false; // Installation alone never arms the phone slot.
  Alarm profile;
  PhoneSyncRecord() {
    strcpy(profile.id, "iphone");
    strcpy(profile.label, "iPhone");
    profile.weekdays = 0;
  }
};

